import * as THREE from './assets/three.module.js';
import {ActivityCamera} from './schoolbus/activity-camera.js?v=76a';
import {schoolBox} from './schoolbus/core.js?v=76a';
import {detailTexture} from './graphics.js?v=76a';
import {findWorldRoute} from './town-navigation.js?v=76a';
export const FAMILY_CHATS={
 mama:[{model:'Hello, Mama! How are you?',reply:'Hello, my little one! I am happy to see you. How are you feeling today?'},{model:'Mama, what are you doing?',reply:'I am looking after our lovely home. Would you like to play with me?'},{model:'Mama, may I have some milk, please?',reply:'Yes, of course. You can choose milk from our fridge. Remember to say thank you!'},{model:'Mama, I like this toy.',reply:'What a lovely toy! Tell me what it can do.'},{model:'Mama, can we read a book?',reply:'Yes! Let us look at a story together. What can you see in the pictures?'}],
 papa:[{model:'Hello, Papa! How are you?',reply:'Hello, my little one! I am glad to see you. Tell me about your day.'},{model:'Papa, what are you doing?',reply:'I am taking a little walk around our home. Shall we play together?'},{model:'Papa, look at my toy!',reply:'That looks fun! What colour is it? Show me how you play with it.'},{model:'Papa, can you help me, please?',reply:'Of course I can help. We can try together. What would you like to do?'},{model:'Papa, I am ready for an adventure.',reply:'Wonderful! Enjoy your adventure, and tell us about it when you come home.'}]
};
export const FAMILY_LINES={near:'Walk over to Mama or Papa, or tap their name above the scene. You can have a little chat together.',waiting:'Let us finish this activity first. Mama and Papa will be happy to chat in a moment.',encourage:'Your turn. Say the sentence out loud, or tell your parent something of your own.',walking:'Let us walk over and say hello.'};
const stops=[[-10,8.8],[9,9.5],[-12,1],[-10,-6],[0,-8.4],[10,-5.5],[12,2],[10,11.5],[-10,11.5]];
const bounds={left:-18.5,right:18.5,top:-12,bottom:14};
// Invented, playful grown-up variants for this game; they are not claims about canonical families.
export class HomeFamily{
 constructor(town,kit){this.town=town;this.kit=kit;this.root=new THREE.Group();this.root.name='Home family';this.root.userData.homeFamily=true;town.house.add(this.root);this.view=new ActivityCamera();this.parents=[];this.character='';this.approaching=null;this.time=0;}
 setCharacter(spec){if(!spec||this.character===spec.name)return false;for(const e of this.parents){e.g.removeFromParent();for(const m of e.owned)m.dispose();}this.parents=[];this.clearance=.8;this.character=spec.name;this.approaching=null;
  for(const [i,role]of ['mama','papa'].entries()){const g=this.kit.puppet(spec),owned=new Set();g.traverse(o=>{if(o.isMesh&&o.material){if(o.material.vertexColors||o.material.isMeshPhysicalMaterial)owned.add(o.material);}});g.name=(i?'Papa':'Mama')+' · '+spec.name+' family';g.userData.neighbour=i;g.userData.homeParent=role;g.userData.adultVariant=true;g.scale.setScalar(i?1.25:1.19);const outfit=new THREE.Group();outfit.name=i?'Papa cardigan':'Mama apron';g.add(outfit);const material=new THREE.MeshStandardMaterial({color:i?0x759aab:0xeab6a4,roughness:.88,bumpMap:detailTexture('cloth'),bumpScale:.015});owned.add(material);const box=(w,h,d,x,y,z,m=material)=>{const q=new THREE.Mesh(schoolBox(w,h,d),m);q.position.set(x,y,z);q.castShadow=q.receiveShadow=true;outfit.add(q);return q;};const trunk=spec.name==='Snuffleupagus';if(trunk){outfit.position.set(0,.1,-.3);box(1.2,.6,1.6,0,1.6,0);}
  else{const garment=new THREE.Mesh(i?new THREE.SphereGeometry(1,24,16):new THREE.CylinderGeometry(.42,.61,1.05,24),material);garment.position.set(0,i?1.02:.93,0);if(i)garment.scale.set(.58,.66,.43);garment.castShadow=garment.receiveShadow=true;outfit.add(garment);if(i){box(.13,.9,.04,0,1.04,.49);for(const side of [-1,1])box(.27,.24,.07,side*.27,.77,.49);}else{box(.16,.47,.065,-.23,1.52,.35);box(.16,.47,.065,.23,1.52,.35);box(.48,.28,.07,0,.83,.49);}const trim=new THREE.MeshStandardMaterial({color:0xffe7c1,roughness:.7});owned.add(trim);for(let j=0;j<3;j++)box(.055,.055,.025,0,.9+j*.18,.49,trim);}
  // Familiar facial identity is retained. Adult clothes and a softer, broader silhouette distinguish the parents.
  const envelope=new THREE.Box3().setFromObject(g),radius=Math.max(.8,Math.abs(envelope.min.x),Math.abs(envelope.max.x),Math.abs(envelope.min.z),Math.abs(envelope.max.z))+.08;const e={radius,g,pos:g.position,yaw:i?-1:1,parentRole:role,identity:{name:i?'Papa':'Mama'},owned,wait:2+i*3,route:null,step:0,walkT:0,talkIndex:-1};e.pos.set(...[stops[i][0],0,stops[i][1]]);g.rotation.y=e.yaw;this.root.add(g);this.parents.push(e);this.clearance=Math.max(this.clearance,radius);
  }return true;
 }
 safe(x,z){if(x<-10.7&&z<-1.8)return false;const walk=(a,b)=>this.town.canWalk(a,b,'house');for(let i=0;i<8;i++){const a=i*Math.PI/4;if(!walk(x+Math.sin(a)*(this.clearance||.8),z+Math.cos(a)*(this.clearance||.8)))return false;}return walk(x,z);}
 route(start,end){return findWorldRoute([start.x,start.z],[end.x,end.z],bounds,(x,z)=>this.safe(x,z));}
 approach(player,index){const e=this.parents[index];if(!e)return null;const delta=player.clone().sub(e.pos).setY(0).normalize();for(const r of [Math.max(2.8,e.radius+1.2),Math.max(3.3,e.radius+1.7),Math.max(3.8,e.radius+2.2)])for(const turn of [0,.6,-.6,1.2,-1.2]){const dir=delta.clone().applyAxisAngle(new THREE.Vector3(0,1,0),turn),end=e.pos.clone().addScaledVector(dir,r);const path=findWorldRoute([player.x,player.z],[end.x,end.z],bounds,(x,z)=>this.town.canWalk(x,z,'house'));if(path)return path;}return null;}
 tick(dt,t,player,{paused=false,reduced=false,talking=null,speaking=false,activeProp=false}={}){if(paused)return;this.time+=dt;for(const [i,e]of this.parents.entries()){let moving=false;const near=e.pos.distanceTo(player.position)<3.6,busy=talking===e||this.approaching===i||activeProp&&e.pos.distanceTo(player.position)<6;
   if(!busy&&!near){e.wait-=dt;if(!e.route&&e.wait<=0){const target=stops[Math.floor(Math.random()*stops.length)],route=this.route(e.pos,new THREE.Vector3(target[0],0,target[1]));e.wait=3+Math.random()*5;if(route&&route.length>1){e.route=route;e.step=1;}}if(e.route){const [x,z]=e.route[e.step],delta=new THREE.Vector3(x-e.pos.x,0,z-e.pos.z),distance=delta.length();if(distance<.12){e.step++;if(e.step>=e.route.length)e.route=null;}else{const next=e.pos.clone().addScaledVector(delta,Math.min(distance,dt*.95)/distance),other=this.parents[1-i];if(this.safe(next.x,next.z)&&next.distanceTo(player.position)>Math.max(2.6,e.radius+1)&&(!other||next.distanceTo(other.pos)>e.radius+other.radius+.15)){e.pos.copy(next);const yaw=Math.atan2(delta.x,delta.z);e.yaw+=Math.atan2(Math.sin(yaw-e.yaw),Math.cos(yaw-e.yaw))*Math.min(1,dt*5);moving=true;}else{e.route=null;e.wait=2;}}}}
   if(busy||near){const yaw=Math.atan2(player.position.x-e.pos.x,player.position.z-e.pos.z);e.yaw+=Math.atan2(Math.sin(yaw-e.yaw),Math.cos(yaw-e.yaw))*Math.min(1,dt*4);}e.g.rotation.y=e.yaw;e.walkT+=moving?dt*5:0;const arms=e.g.userData.arms||[],legs=e.g.userData.legs||[];for(const [j,a]of arms.entries()){a.rotation.x=moving&&!reduced?Math.sin(e.walkT+j*Math.PI)*.35:Math.sin(t*1.3+j)*.025;a.rotation.z=talking===e&&j===1?-.65:(j===0?-.22:.22);}for(const [j,l]of legs.entries())l.rotation.x=moving&&!reduced?Math.sin(e.walkT+j*Math.PI)*.24:0;const mouth=e.g.userData.mouth;if(mouth)mouth.scale.y=talking===e&&speaking&&!reduced?.8+Math.abs(Math.sin(t*10))*.3:1;e.pos.y=moving&&!reduced?Math.abs(Math.sin(e.walkT))*.025:0;
  }}
 camera(camera,player,e,position,look){const roots=this.town.house.children.filter(o=>o!==this.root).flatMap(o=>o.userData.homeDepth?o.children:[o]);roots.push(...this.parents.map(p=>p.g));this.town.house.updateMatrixWorld(true);this.view.prepare(roots,player,[e.g]);const preferred=player.position.clone().lerp(e.pos,.5).add(new THREE.Vector3(3,3,8));this.view.solve(camera,preferred,look,position,{key:e.parentRole,elevations:[.14,.24,.36,.48],preferredElevation:.2});}
 nextChat(e,random=Math.random){const lines=FAMILY_CHATS[e.parentRole];e.talkIndex=(e.talkIndex+1+(e.talkIndex<0?Math.floor(random()*lines.length):0))%lines.length;return lines[e.talkIndex];}
}
